import{_ as e,o as r,c as t,a2 as l}from"./chunks/framework.BV21bweQ.js";const u=JSON.parse('{"title":"古代遗迹","description":"","frontmatter":{},"headers":[],"relativePath":"表层/地理/古代遗迹.md","filePath":"表层/地理/古代遗迹.md","lastUpdated":1787066340000}'),o={name:"表层/地理/古代遗迹.md"};function i(n,a,h,s,d,c){return r(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="古代遗迹" tabindex="-1">古代遗迹 <a class="header-anchor" href="#古代遗迹" aria-label="Permalink to &quot;古代遗迹&quot;">​</a></h1><h2 id="梯形神殿废墟-旧都" tabindex="-1">梯形神殿废墟（旧都） <a class="header-anchor" href="#梯形神殿废墟-旧都" aria-label="Permalink to &quot;梯形神殿废墟（旧都）&quot;">​</a></h2><p>共同体时期的梯形神殿是共同体的政治中心与神明居所。灾变中，神殿被炸翻，旧都随之沉入水下，如今只剩下沉没于水下的废墟。</p><h2 id="旧都水下之城" tabindex="-1">旧都水下之城 <a class="header-anchor" href="#旧都水下之城" aria-label="Permalink to &quot;旧都水下之城&quot;">​</a></h2><p>共同体首都于灾变中地面下沉、河水涌入，短短数日内沦为<strong>水下之城</strong>。如今整座城市沉没于水域之中，成为一片水下遗迹。</p><h2 id="大陆上的古环形山" tabindex="-1">大陆上的古环形山 <a class="header-anchor" href="#大陆上的古环形山" aria-label="Permalink to &quot;大陆上的古环形山&quot;">​</a></h2><p>大陆上随处可见或大或小的环形山，被普遍视为自然地形地貌。然而其规整的形态令人生疑——看起来的确不像是自然形成的。至于其真正的来历，无人能够解释。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../../中层/历史/正传历史" class="layer-link" data-layer="中层">正传历史</a></p></blockquote><h2 id="六边形沙漠" tabindex="-1">六边形沙漠 <a class="header-anchor" href="#六边形沙漠" aria-label="Permalink to &quot;六边形沙漠&quot;">​</a></h2><p>大陆上一片诡异的沙漠，呈规则的六边形几何特征，温度奇高且逐年升温，逐渐成为无活物可生存的无人区。其形成原因不明。</p><h2 id="通天光柱" tabindex="-1">通天光柱 <a class="header-anchor" href="#通天光柱" aria-label="Permalink to &quot;通天光柱&quot;">​</a></h2><p>大陆某处有一道通天彻地的纯白光柱，天空在扭曲，大地被撕裂。没有人知道发生了什么，更没人知道光柱底下那些奇奇怪怪的构筑物是什么，因为没有人能活着靠近那根光柱。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../../中层/历史/前传超算纪元" class="layer-link" data-layer="中层">前传超算纪元</a></p></blockquote><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./自然生态">自然生态</a></li><li><a href="./../历史/">表层历史</a></li><li><a href="./../../中层/世界/特殊地点" class="layer-link" data-layer="中层">特殊地点</a></li></ul><hr>',17)])])}const _=e(o,[["render",i]]);export{u as __pageData,_ as default};
